//! Raw bindings to the NVIDIA SDK headers, for every driver version
//! `abi.toml` names.
//!
//! Generated by `cargo xtask abi`. Do not edit: the next run discards
//! hand work, and CI checks that a run produces no diff.
//!
//! The shape, and why it is this shape:
//!
//!   * [`stable`] holds every name that is the same on every version.
//!     It is re-exported at the crate root, so `nvrm_sys::NVOS64_PARAMETERS`
//!     means what it always meant.
//!   * one module per version holds what is not. Those names are NOT
//!     re-exported at the root, because two versions would collide there
//!     and the collision is the whole point: they are different types.
//!   * [`RmAbi`] names the ones a caller has to be generic over.
//!
//! Features are additive. Each `v<NNN>` enables a module and disables
//! nothing; all of them at once compiles, and with exactly one enabled
//! the dispatch in [`DriverVersion`] has a single arm.
#![allow(non_upper_case_globals, non_camel_case_types, non_snake_case)]
#![allow(dead_code, clippy::all)]

/// Asserts a measured layout: the size, the alignment and one offset
/// per field, all of them read from `manifests/<version>.json`.
///
/// This is what keeps the committed source and the committed evidence
/// together. Breaking it means one of the two moved without the other.
macro_rules! assert_layout {
    ($t:ty, size = $size:expr, align = $align:expr $(, $field:ident @ $off:expr)* $(,)?) => {
        const _: () = {
            assert!(::core::mem::size_of::<$t>() == $size);
            assert!(::core::mem::align_of::<$t>() == $align);
            $( assert!(::core::mem::offset_of!($t, $field) == $off); )*
        };
    };
}

mod version;
pub use version::{assert_driver_version, detect, running_driver_version};

pub mod stable;
pub use stable::*;

#[cfg(feature = "v580")]
pub mod v580;
#[cfg(feature = "v595")]
pub mod v595;
#[cfg(feature = "v610")]
pub mod v610;
#[cfg(feature = "v615")]
pub mod v615;

/// The driver version this crate defaults to: the one in `DRIVER_VERSION`
/// at the repository root, and the one the `default` feature enables.
pub const DRIVER_VERSION: &str = "610.57.04";

/// Every driver version this crate carries a layout for, oldest first.
pub const SUPPORTED_VERSIONS: &[&str] = &["580.178.04", "595.99.02", "610.57.04", "615.71.09"];

/// Which supported driver a running system has.
///
/// Guest and host driver versions are assumed equal, so this is read
/// once, on the host, and carried.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DriverVersion {
    /// 580.178.04
    #[cfg(feature = "v580")]
    V580,
    /// 595.99.02
    #[cfg(feature = "v595")]
    V595,
    /// 610.57.04
    #[cfg(feature = "v610")]
    V610,
    /// 615.71.09
    #[cfg(feature = "v615")]
    V615,
}

impl DriverVersion {
    /// The version string as `/proc/driver/nvidia/version` spells it.
    pub fn as_str(self) -> &'static str {
        match self {
            #[cfg(feature = "v580")]
            DriverVersion::V580 => "580.178.04",
            #[cfg(feature = "v595")]
            DriverVersion::V595 => "595.99.02",
            #[cfg(feature = "v610")]
            DriverVersion::V610 => "610.57.04",
            #[cfg(feature = "v615")]
            DriverVersion::V615 => "615.71.09",
        }
    }

    /// The supported version this string names, or `None`.
    ///
    /// A version that is not here is REFUSED rather than approximated.
    /// A minor release joins a branch by having the same manifest, which
    /// gives it its own entry in `abi.toml`; a version with no entry has
    /// not been measured, and guessing which layout it takes is the one
    /// mistake this whole crate exists to prevent.
    pub fn from_version_string(s: &str) -> Option<Self> {
        match s {
            #[cfg(feature = "v580")]
            "580.178.04" => Some(DriverVersion::V580),
            #[cfg(feature = "v595")]
            "595.99.02" => Some(DriverVersion::V595),
            #[cfg(feature = "v610")]
            "610.57.04" => Some(DriverVersion::V610),
            #[cfg(feature = "v615")]
            "615.71.09" => Some(DriverVersion::V615),
            _ => None,
        }
    }
}

/// The MODULE of [`DRIVER_VERSION`].
///
/// For the handful of names that cannot go through [`RmAbi`] at all
/// because some supported version does not have them -- the NVA083
/// virtual-display constants, which arrive with R595. Reaching for
/// this is a statement that the code only works on drivers that have
/// the name, and the compiler cannot check that for you.
#[cfg(feature = "v610")]
pub use v610 as default_version;

/// The ABI of [`DRIVER_VERSION`].
///
/// For code that is deliberately single-version -- a test, a
/// diagnostic, a tool that only ever runs beside the driver this
/// build was made for. Anything that has to work on more than one
/// takes `A: RmAbi` and gets it from [`dispatch`].
#[cfg(feature = "v610")]
pub type DefaultAbi = V610;

/// The types whose layout depends on the driver version, and the sizes
