/// A piece of work that is generic over the ABI, so that [`dispatch`]
/// can hand it the right one.
///
/// A closure cannot do this: it would have to be generic over a type
/// parameter it does not have. A one-method trait can, and costs
/// nothing -- with a single feature enabled the match below has one arm
/// and the call is direct.
pub trait AbiVisitor {
    /// What the work produces. The same type for every version, which
    /// is what lets one match answer for all of them.
    type Out;
    fn visit<A: RmAbi>(self) -> Self::Out;
}

/// THE dispatch point. The only `match` on [`DriverVersion`] in the
/// tree, by construction: everything downstream of it is generic over
/// `A: RmAbi` and never asks again.
///
/// With one version's feature enabled this match has one arm and
/// disappears; with several it is one branch, once, at start-up.
pub fn dispatch<V: AbiVisitor>(version: DriverVersion, work: V) -> V::Out {
    match version {
        #[cfg(feature = "v580")]
        DriverVersion::V580 => work.visit::<V580>(),
        #[cfg(feature = "v595")]
        DriverVersion::V595 => work.visit::<V595>(),
        #[cfg(feature = "v610")]
        DriverVersion::V610 => work.visit::<V610>(),
        #[cfg(feature = "v615")]
        DriverVersion::V615 => work.visit::<V615>(),
    }
}

